examples.template:
@OptIn(ExperimentalMonarchApi::class)
Column {
    MonarchTextField(
        value = prompt,
        onValueChange = { prompt = it },
        label = {{promptLabel}},
        singleLine = false,
        minLines = 3,
        labelVisibility = MonarchTextFieldLabelVisibility.Hidden,
    )
    MonarchAiVoiceInput(
        onTranscript = { text, final ->
            if (final) prompt = listOf(prompt, text).filter { it.isNotEmpty() }.joinToString(" ")
        },
        recognizer = recognizer,
        showLevel = false,
        icon = { MonarchIcon(SampleIcons.Mic, contentDescription = null) },
        labels = MonarchAiVoiceInputLabels(dictate = {{dictate}}),
    )
}

examples.setupTemplate:
var prompt by remember { mutableStateOf("") }
// The app's own speech engine; the default is the device recogniser.
val recognizer = object : MonarchAiSpeechRecognizer {
    override fun isAvailable(locale: Locale?) = true
    override fun start(locale: Locale?, continuous: Boolean): Flow<MonarchAiSpeechEvent> = emptyFlow()
    override fun stop() = Unit
}

